-- ============================================================================
--  DORMITORY MANAGEMENT SYSTEM — Supabase schema (replaces data.json)
--  Run this ONCE in the Supabase SQL editor before the first deploy.
-- ============================================================================

create table if not exists public.app_data (
  collection  text primary key,
  payload     jsonb       not null default '{}'::jsonb,
  updated_at  timestamptz not null default now()
);

create index if not exists app_data_updated_at_idx on public.app_data (updated_at desc);

-- The backend connects with the service role key only, so the Data API stays
-- locked down: RLS is enabled and no anon/authenticated policy is created.
alter table public.app_data enable row level security;

grant all on public.app_data to service_role;

-- ============================================================================
--  SEED — current live data migrated out of data.json.
--  Existing rows are never overwritten, so re-running this file is safe.
-- ============================================================================
on conflict (collection) do nothing;

-- Image store for /uploads/<file> (Render disks are ephemeral).
on conflict (collection) do nothing;
